-- Esquema nuevo e independiente de Django. Flyway administra esta versión.
CREATE TABLE mod05_usuario (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 usuario varchar(150) NOT NULL UNIQUE,
 nombre varchar(200) NOT NULL,
 password_hash varchar(200) NOT NULL,
 activo boolean NOT NULL DEFAULT true
);
CREATE TABLE mod05_usuario_rol (
 usuario_id bigint NOT NULL REFERENCES mod05_usuario(id),
 rol varchar(60) NOT NULL CHECK (rol IN ('Jefe de sección','Ingeniero de campo','Practicante autorizado')),
 PRIMARY KEY(usuario_id, rol)
);
CREATE TABLE "mod05_archivo" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nombre_original" varchar(200) NOT NULL, "tipo_mime" varchar(100) NOT NULL, "tamano_bytes" bigint NOT NULL CHECK ("tamano_bytes" >= 0), "ruta_almacenamiento" varchar(400) NOT NULL UNIQUE, "hash_contenido" varchar(64) NOT NULL);
CREATE TABLE "mod05_areaverde" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nombre" varchar(150) NOT NULL, "activo" boolean NOT NULL);
CREATE TABLE "mod05_contrato" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "numero" varchar(40) NOT NULL UNIQUE, "vigencia_inicio" date NOT NULL, "vigencia_fin" date NOT NULL);
CREATE TABLE "mod05_proveedor" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "razon_social" varchar(200) NOT NULL, "ruc" varchar(11) NULL UNIQUE, "activo" boolean NOT NULL);
CREATE TABLE "mod05_tiposervicio" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nombre" varchar(120) NOT NULL, "ejecutor" varchar(40) NOT NULL, "es_riesgo" boolean NOT NULL, "activo" boolean NOT NULL);
CREATE TABLE "mod05_unidadinstitucional" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nombre" varchar(150) NOT NULL UNIQUE, "provisional" boolean NOT NULL, "activo" boolean NOT NULL);
CREATE TABLE "mod05_unidadmedida" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nombre" varchar(80) NOT NULL, "simbolo" varchar(20) NOT NULL);
CREATE TABLE "mod05_atenciontercerizada" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "fecha_creacion" timestamp with time zone NOT NULL, "fecha_modificacion" timestamp with time zone NOT NULL, "codigo" varchar(35) NOT NULL UNIQUE, "clase" varchar(30) NOT NULL, "descripcion" text NOT NULL, "origen" varchar(30) NOT NULL, "numero_orden_compra" varchar(30) NOT NULL, "fecha_orden_compra" timestamp with time zone NULL, "fecha_hora_inicio" timestamp with time zone NULL, "fecha_hora_fin" timestamp with time zone NULL, "estado" varchar(40) NOT NULL, "es_riesgo" boolean NOT NULL, "acuerdo_unidad" boolean NULL, "fecha_acuerdo_unidad" date NULL, "comentarios_acuerdo_unidad" text NOT NULL, "solicitado_por_id" bigint NOT NULL, "usuario_creacion_id" bigint NOT NULL, "usuario_modificacion_id" bigint NOT NULL, "contrato_id" bigint NOT NULL, "tipo_servicio_id" bigint NOT NULL, "unidad_solicitante_id" bigint NULL);
CREATE TABLE "mod05_ejemplar" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "codigo" varchar(40) NOT NULL UNIQUE, "area_verde_id" bigint NULL);
CREATE TABLE "mod05_alcanceatencion" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "metrado" numeric(12, 2) NULL, "area_verde_id" bigint NULL, "atencion_id" bigint NOT NULL, "ejemplar_id" bigint NULL, "unidad_medida_id" bigint NULL);
CREATE TABLE "mod05_historialestado" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "estado_anterior" varchar(40) NOT NULL, "estado_nuevo" varchar(40) NOT NULL, "fecha_hora" timestamp with time zone NOT NULL, "atencion_id" bigint NOT NULL, "usuario_id" bigint NOT NULL);
ALTER TABLE "mod05_contrato" ADD COLUMN "proveedor_id" bigint NOT NULL CONSTRAINT "mod05_contrat_proveedor_id_05a5f974_fk_terceriza" REFERENCES "mod05_proveedor"("id") DEFERRABLE INITIALLY DEFERRED; SET CONSTRAINTS "mod05_contrat_proveedor_id_05a5f974_fk_terceriza" IMMEDIATE;
CREATE TABLE "mod05_registroauditoria" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "entidad" varchar(60) NOT NULL, "registro_id" bigint NOT NULL, "accion" varchar(40) NOT NULL, "fecha_hora" timestamp with time zone NOT NULL, "valores_anteriores" jsonb NOT NULL, "valores_nuevos" jsonb NOT NULL, "motivo" text NOT NULL, "usuario_id" bigint NOT NULL);
CREATE TABLE "mod05_reporteproveedor" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "fecha_creacion" timestamp with time zone NOT NULL, "fecha_modificacion" timestamp with time zone NOT NULL, "revision" integer NOT NULL CHECK ("revision" >= 0), "fecha_recepcion" date NOT NULL, "resumen" text NOT NULL, "atencion_id" bigint NOT NULL, "usuario_creacion_id" bigint NOT NULL, "usuario_modificacion_id" bigint NOT NULL);
CREATE TABLE "mod05_archivoasociado" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "categoria" varchar(30) NOT NULL, "descripcion" varchar(200) NOT NULL, "alcance_id" bigint NULL, "archivo_id" bigint NOT NULL UNIQUE, "reporte_id" bigint NOT NULL);
ALTER TABLE "mod05_contrato" ADD COLUMN "tipo_servicio_id" bigint NOT NULL CONSTRAINT "mod05_contrat_tipo_servicio_id_277414d4_fk_terceriza" REFERENCES "mod05_tiposervicio"("id") DEFERRABLE INITIALLY DEFERRED; SET CONSTRAINTS "mod05_contrat_tipo_servicio_id_277414d4_fk_terceriza" IMMEDIATE;
ALTER TABLE "mod05_reporteproveedor" ADD CONSTRAINT "mod05_revision_unica" UNIQUE ("atencion_id", "revision");
ALTER TABLE "mod05_contrato" ADD CONSTRAINT "mod05_contrato_fechas" CHECK ("vigencia_fin" >= ("vigencia_inicio"));
ALTER TABLE "mod05_atenciontercerizada" ADD CONSTRAINT "mod05_atencion_fechas" CHECK (("fecha_hora_fin" IS NULL OR ("fecha_hora_inicio" IS NOT NULL AND "fecha_hora_fin" >= ("fecha_hora_inicio"))));
ALTER TABLE "mod05_atenciontercerizada" ADD CONSTRAINT "mod05_origen_unidad" CHECK ((("origen" = 'SolicitudUnidad' AND "unidad_solicitante_id" IS NOT NULL) OR ("origen" IN ('Demanda', 'ProgramacionEstacional') AND "unidad_solicitante_id" IS NULL)));
ALTER TABLE "mod05_alcanceatencion" ADD CONSTRAINT "mod05_alcance_destino" CHECK ((("area_verde_id" IS NOT NULL AND "ejemplar_id" IS NULL) OR ("area_verde_id" IS NULL AND "ejemplar_id" IS NOT NULL)));
ALTER TABLE "mod05_alcanceatencion" ADD CONSTRAINT "mod05_alcance_area_unica" UNIQUE ("atencion_id", "area_verde_id");
ALTER TABLE "mod05_alcanceatencion" ADD CONSTRAINT "mod05_alcance_ejemplar_unico" UNIQUE ("atencion_id", "ejemplar_id");
ALTER TABLE "mod05_alcanceatencion" ADD CONSTRAINT "mod05_metrado_unidad" CHECK ((("metrado" IS NULL AND "unidad_medida_id" IS NULL) OR ("metrado" >= 0 AND "metrado" IS NOT NULL AND "unidad_medida_id" IS NOT NULL)));
