CREATE FUNCTION mod05_rechazar_cambio_historial() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'El historial MOD-05 solo permite inserciones';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER mod05_auditoria_inmutable BEFORE UPDATE OR DELETE ON mod05_registroauditoria
FOR EACH ROW EXECUTE FUNCTION mod05_rechazar_cambio_historial();
CREATE TRIGGER mod05_estados_inmutables BEFORE UPDATE OR DELETE ON mod05_historialestado
FOR EACH ROW EXECUTE FUNCTION mod05_rechazar_cambio_historial();
